	plan.LastUpdated = types.StringValue(string(result.GetLastUpdated()))
	plan.Name = types.StringValue(string(result.GetName()))
	if v := result.GetTitle(); v != "" {
		plan.Title = types.StringValue(string(v))
	} else {
		plan.Title = types.StringNull()
	}
	plan.Type = types.StringValue(string(result.GetType()))

